const glowCache = new Map();
function glow(color){
  let s=glowCache.get(color); if(s) return s;
  const size=96; const c=document.createElement('canvas'); c.width=c.height=size;
  const g=c.getContext('2d');
  const grd=g.createRadialGradient(size/2,size/2,0,size/2,size/2,size/2);
  grd.addColorStop(0, rgba(color,1));
  grd.addColorStop(0.18, rgba(color,.85));
  grd.addColorStop(0.45, rgba(color,.28));
  grd.addColorStop(1, rgba(color,0));
  g.fillStyle=grd; g.fillRect(0,0,size,size);
  glowCache.set(color,c); return c;
}
