    if(this.ac){ if(this.ac.state==='suspended') this.ac.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext; if(!AC) return;
    this.ac = new AC();
    this.master = this.ac.createGain(); this.master.gain.value = 0.24; this.master.connect(this.ac.destination);
    const len = this.ac.sampleRate*0.5; const buf=this.ac.createBuffer(1,len,this.ac.sampleRate); const d=buf.getChannelData(0);
