Touch joystick:
```js
const stick={x:0,y:0,active:false,id:null};
const joy=$('joystick'), knob=$('stick-knob');
function setStick(e){
  const r=joy.getBoundingClientRect(); const cx=r.left+r.width/2, cy=r.top+r.height/2;
  let dx=e.clientX-cx, dy=e.clientY-cy;
  const max=r.width*0.32; const d=Math.hypot(dx,dy)||1;
  if(d>max){ dx=dx/d*max; dy=dy/d*max; }
  knob.style.transform=`translate(-50%,-50%) translate(${dx}px,${dy}px)`;
  const nx=dx/max, ny=dy/max;
  const dead=0.15; const len=Math.hypot(nx,ny);
  if(len<dead){ stick.x=0; stick.y=0; } else { const k=(len-dead)/(1-dead)/len; stick.x=nx*k; stick.y=ny*k; }
}
joy.addEventListener('pointerdown', e=>{ e.preventDefault(); stick.active=true; stick.id=e.pointerId; joy.setPointerCapture(e.pointerId); setStick(e); });
joy.addEventListener('pointermove', e=>{ if(stick.active && e.pointerId===stick.id) setStick(e); });
function endStick(e){ if(!stick.active) return; stick.active=false; stick.x=stick.y=0; knob.style.transform='translate(-50%,-50%)'; }
joy.addEventListener('pointerup', endStick); pointercancel; lostpointercapture.
```
