function updatePlayer(dt){
  const p=G.player;
  if(!p || p.dead) return;
  // input
  let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);
  let iy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);
  ix+=stick.x; iy+=stick.y;
  const len=Math.hypot(ix,iy);
  if(len>1){ ix/=len; iy/=len; }
  // aim
  let aimA;
  const target=nearestEnemy(p.x,p.y,1400);
  if(G.isTouch || !G.mouseActive){
    if(target) aimA=Math.atan2(target.y-p.y,target.x-p.x);
    else aimA=p.angle;
  } else {
    aimA=Math.atan2(G.mouse.y-p.y,G.mouse.x-p.x);
    if(target){ const ta=Math.atan2(target.y-p.y,target.x-p.x); if(Math.abs(angleDelta(ta,aimA))<0.14) aimA=ta; }
  }
  p.aimAngle=aimA;
  p.angle += angleDelta(aimA,p.angle)*Math.min(1,dt*16);
  // dash
  if(p.dashTime>0){
    p.dashTime-=dt;
    p.x += p.dashX*760*dt; p.y += p.dashY*760*dt;
    p.invuln=Math.max(p.invuln,0.05);
    if(Math.random()<dt*70) addParticle(p.x,p.y,C.cyan, rnd(2,5), rnd(30,90), 0.35);
    // dash damage handled by collision loop? Skip
  } else {
    p.vx += (ix*p.speed - p.vx)*Math.min(1,dt*14);
    p.vy += (iy*p.speed - p.vy)*Math.min(1,dt*14);
    p.x += p.vx*dt; p.y += p.vy*dt;
  }
  // clamp
  p.x=clamp(p.x,p.r+6,W-p.r-6); p.y=clamp(p.y,p.r+6,H-p.r-6);
  if(p.x<=p.r+6||p.x>=W-p.r-6) p.vx=0; ...
  p.dashCd=Math.max(0,p.dashCd-dt);
  p.invuln=Math.max(0,p.invuln-dt);
  p.fireCd-=dt;
  // thruster trail
  const spd=Math.hypot(p.vx,p.vy);
  if(spd>40){ p.trailT-=dt; if(p.trailT<=0){ p.trailT=0.035; addParticle(p.x-Math.cos(p.angle)*10, p.y-Math.sin(p.angle)*10, C.cyan, rnd(1.5,3.5), rnd(10,40), .3, p.vx*-0.1, p.vy*-0.1); } }
  // fire
  if(p.fireCd<=0 && target){ fire(); p.fireCd=p.fireRate; }
  // drone
  updateDrones(dt,target);
}
```
