const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(600);
  const title = await page.evaluate(() => ({ state: window.RiftSwarm.state, fonts: document.fonts.status }));
  console.log('TITLE', title);
  await page.screenshot({ path: '/tmp/opencode/title.png' });
  await page.evaluate(() => {
    window.__frames = 0;
    const tick = () => { window.__frames++; requestAnimationFrame(tick); };
    requestAnimationFrame(tick);
  });
  await page.click('#play-btn');
  for (let i = 0; i < 4; i++) {
    await page.waitForTimeout(1000);
    const info = await page.evaluate(() => ({ state: window.RiftSwarm.state, frames: window.__frames }));
    console.log('AFTER', i + 1, 's', info);
  }
  await page.screenshot({ path: '/tmp/opencode/game4s.png' });
  // play a little: move and aim
  await page.mouse.move(900, 400);
  await page.keyboard.down('KeyD');
  await page.waitForTimeout(1500);
  await page.keyboard.up('KeyD');
  await page.keyboard.press('Space');
  await page.waitForTimeout(1500);
  const after = await page.evaluate(() => window.RiftSwarm.state);
  console.log('AFTER INPUT', after);
  await page.screenshot({ path: '/tmp/opencode/game6s.png' });
  console.log('ERRORS', errors);
  await browser.close();
})();

const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));

async function fps(page, ms) {
  const start = await page.evaluate(() => { window.__f = 0; const t = () => { window.__f++; requestAnimationFrame(t); }; requestAnimationFrame(t); return performance.now(); });
  await page.waitForTimeout(ms);
  return await page.evaluate((s) => ({ frames: window.__f, ms: Math.round(performance.now() - s) }), start);
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  console.log('title fps', await fps(page, 2000));
  await page.click('#play-btn');
  await page.waitForTimeout(1500);
  console.log('game fps', await fps(page, 2000));
  await page.evaluate(() => { document.querySelector('.fx-layer').style.display = 'none'; });
  console.log('no fx fps', await fps(page, 2000));
  await page.evaluate(() => { document.querySelector('#hud').style.display = 'none'; });
  console.log('no hud fps', await fps(page, 2000));
  await page.evaluate(() => { document.querySelector('#game').style.display = 'none'; });
  console.log('no canvas fps', await fps(page, 2000));
  await browser.close();
})();

