const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));

async function fps(page, ms) {
  const start = await page.evaluate(() => { window.__f = 0; const t = () => { window.__f++; requestAnimationFrame(t); }; requestAnimationFrame(t); return performance.now(); });
  await page.waitForTimeout(ms);
  return await page.evaluate((s) => Math.round((window.__f / (performance.now() - s)) * 1000), start);
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  console.log('title base', await fps(page, 1500));
  await page.addStyleTag({ content: '.screen-title{background:transparent !important}' });
  console.log('title no scrim', await fps(page, 1500));
  await page.evaluate(() => { document.querySelector('#title-screen').style.display = 'none'; });
  console.log('title canvas only', await fps(page, 1500));
  await page.evaluate(() => { document.querySelector('#title-screen').style.display = ''; });
  await page.addStyleTag({ content: '.logo{filter:none !important} .logo-rift,.logo-swarm{filter:none !important}' });
  console.log('title no logo filter', await fps(page, 1500));
  await page.reload({ waitUntil: 'load' });
