  await page.addStyleTag({ content: '.hud{text-shadow:none !important} .hud *{text-shadow:none !important;box-shadow:none !important}' });
  console.log('game no hud shadows', await fps(page, 1500));
  await page.evaluate(() => { document.querySelector('#hud').style.display = 'none'; });
  console.log('game no hud', await fps(page, 1500));
  await browser.close();
})();

