const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const out = '/tmp/opencode/ui';
require('node:fs').mkdirSync(out, { recursive: true });

async function desktop(browser) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.screenshot({ path: out + '/desktop-title.png' });
  await page.click('#play-btn');
  await page.waitForTimeout(1000);
  await page.evaluate(() => window.RiftSwarm.addXp(20));
  await page.waitForTimeout(400);
  await page.screenshot({ path: out + '/desktop-levelup.png' });
  console.log('levelup state', await page.evaluate(() => window.RiftSwarm.state));
  // choose upgrades until the overlay closes
  for (let i = 0; i < 5; i++) {
    const mode = await page.evaluate(() => window.RiftSwarm.state.mode);
    if (mode !== 'levelup') break;
    await page.locator('#upgrade-cards .upgrade-card').first().click();
    await page.waitForTimeout(250);
  }
  console.log('after choose', await page.evaluate(() => window.RiftSwarm.state));
  await page.keyboard.press('KeyP');
  await page.waitForTimeout(300);
  await page.screenshot({ path: out + '/desktop-pause.png' });
  await page.keyboard.press('KeyP');
  await page.evaluate(() => window.RiftSwarm.setWave(5));
  await page.waitForTimeout(2600);
  await page.screenshot({ path: out + '/desktop-boss.png' });
  console.log('boss state', await page.evaluate(() => window.RiftSwarm.state));
  await page.evaluate(() => window.RiftSwarm.hurt(999));
  await page.waitForTimeout(700);
  await page.screenshot({ path: out + '/desktop-gameover.png' });
  console.log('gameover state', await page.evaluate(() => window.RiftSwarm.state));
  console.log('desktop errors', errors);
  await page.close();
}

async function mobile(browser, touch) {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: touch, isMobile: touch, deviceScaleFactor: 2 });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.screenshot({ path: out + (touch ? '/mobile-touch-title.png' : '/mobile-title.png') });
  await page.click('#play-btn');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: out + (touch ? '/mobile-touch-game.png' : '/mobile-game.png') });
  console.log('touch?', touch, 'state', await page.evaluate(() => window.RiftSwarm.state));
  if (!touch) {
    await page.evaluate(() => window.RiftSwarm.addXp(20));
    await page.waitForTimeout(400);
    await page.screenshot({ path: out + '/mobile-levelup.png' });
    for (let i = 0; i < 5; i++) {
      const mode = await page.evaluate(() => window.RiftSwarm.state.mode);
      if (mode !== 'levelup') break;
      await page.locator('#upgrade-cards .upgrade-card').first().click();
      await page.waitForTimeout(200);
    }
    await page.evaluate(() => window.RiftSwarm.setWave(5));
    await page.waitForTimeout(2200);
    await page.screenshot({ path: out + '/mobile-boss.png' });
    await page.evaluate(() => window.RiftSwarm.hurt(999));
    await page.waitForTimeout(600);
    await page.screenshot({ path: out + '/mobile-gameover.png' });
  }
  console.log('mobile errors', errors);
  await context.close();
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  await desktop(browser);
  await mobile(browser, false);
  await mobile(browser, true);
  await browser.close();
})();

