const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.click('#play-btn');
  await page.waitForTimeout(600);

  // Grant a run's worth of upgrades.
  for (let i = 0; i < 12; i++) {
    await page.evaluate(() => window.RiftSwarm.addXp(60));
    await page.waitForTimeout(80);
    for (let k = 0; k < 12; k++) {
      const mode = await page.evaluate(() => window.RiftSwarm.state.mode);
      if (mode !== 'levelup') break;
      await page.locator('#upgrade-cards .upgrade-card').nth(k % 3).click();
      await page.waitForTimeout(60);
    }
  }
  const s0 = await page.evaluate(() => window.RiftSwarm.state);
  console.log('UPGRADED', JSON.stringify(s0));
  await page.evaluate(() => window.RiftSwarm.setWave(5));
  await page.waitForTimeout(1500);

  const keys = ['KeyW', 'KeyA', 'KeyS', 'KeyD'];
  let held = null;
  let tick = 0;
  const start = Date.now();
  while (Date.now() - start < 30000) {
    const mode = await page.evaluate(() => window.RiftSwarm.state.mode);
    if (mode === 'gameover') break;
    if (mode === 'levelup') {
      await page.locator('#upgrade-cards .upgrade-card').first().click();
      await page.waitForTimeout(120);
      continue;
    }
    if (held) await page.keyboard.up(held);
    held = keys[Math.floor(tick / 2) % 4];
    await page.keyboard.down(held);
    if (tick % 4 === 0) await page.keyboard.press('Space');
    if (tick % 4 === 0) console.log('t=' + Math.round((Date.now() - start) / 1000) + 's', JSON.stringify(await page.evaluate(() => window.RiftSwarm.state)));
    tick++;
    await page.waitForTimeout(300);
  }
  if (held) await page.keyboard.up(held);
  console.log('FINAL', JSON.stringify(await page.evaluate(() => window.RiftSwarm.state)));
  console.log('errors', errors);
  await page.screenshot({ path: '/tmp/opencode/boss-fight.png' });
  await browser.close();
})();

