  text-shadow: 0 0 16px rgba(69, 244, 255, 0.65);
  white-space: nowrap;
}
.boss-wrap { width: min(280px, 34vw); margin-top: 6px; }
.boss-name {
  font-family: var(--display);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: var(--red);
  text-shadow: 0 0 12px rgba(255, 84, 112, 0.8);
}
.meter.boss { height: 8px; border-color: rgba(255, 84, 112, 0.4); }
.meter.boss i {
  background: linear-gradient(90deg, #ff2f57, #ff7aa0);
}

.score-block { text-align: right; }
.score {
  font-family: var(--body);
  font-size: clamp(24px, 2.6vw, 36px);
  font-weight: 700;
  letter-spacing: 0.1em;
  line-height: 0.9;
  color: #f2ffff;
  text-shadow: 0 0 20px rgba(69, 244, 255, 0.55);
  font-variant-numeric: tabular-nums;
}
#best-inline {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: rgba(150, 190, 215, 0.62);
}
.combo {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.06em;
  color: var(--amber);
  text-shadow: 0 0 16px rgba(255, 200, 87, 0.9);
  animation: comboPop 0.18s ease-out;

